css:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --bg: #ffffff;
  --txt: #141414;
  --dim: #707070;
  --border: rgba(0, 0, 0, 0.08);
  --font-body: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-head: 'Cinzel', Georgia, serif;
}
body {
  background: var(--bg);
  color: var(--txt);
  font-family: var(--font-body);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* Luxury Header */
.gazu-top-bar {
  background: #000;
  color: #fff;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  text-align: center;
  padding: 10px 20px;
}
.gazu-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 48px;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(12px);
  z-index: 100;
}
.gazu-brand {
  font-family: var(--font-head);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--txt);
}
.gazu-nav {
  display: flex;
  gap: 32px;
  align-items: center;
}
.gazu-nav a {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--dim);
  text-decoration: none;
  transition: color 0.2s;
}
.gazu-nav a:hover, .gazu-nav a.is-active {
  color: var(--txt);
}
.gazu-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}
.gazu-bag-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #111;
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 9px 18px;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  cursor: pointer;
  transition: opacity 0.2s;
}
.gazu-bag-btn:hover { opacity: 0.85; }
.gazu-bag-count {
  background: #fff;
  color: #111;
  border-radius: 50%;
  width: 18px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 700;
}

/* Hero Section */
.archive-hero {
  padding: 70px 48px 40px;
  max-width: 1440px;
  margin: 0 auto;
  text-align: center;
}
.archive-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: #888;
  display: block;
  margin-bottom: 12px;
}
.archive-title {
  font-family: var(--font-head);
  font-size: 38px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--txt);
  margin-bottom: 16px;
}
.archive-sub {
  font-size: 14px;
  color: #666;
  max-width: 650px;
  margin: 0 auto;
  line-height: 1.6;
}

/* Controls Bar */
.archive-controls {
  max-width: 1440px;
  margin: 30px auto 40px;
  padding: 0 48px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 24px;
}
.archive-filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.archive-filter-btn {
  background: #f7f7f7;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 8px 18px;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dim);
  cursor: pointer;
  transition: all 0.2s;
}
.archive-filter-btn:hover, .archive-filter-btn.is-active {
  background: #111;
  color: #fff;
  border-color: #111;
}
.archive-meta {
  display: flex;
  align-items: center;
  gap: 20px;
}
.archive-count {
  font-size: 12px;
  font-weight: 600;
  color: #777;
  letter-spacing: 0.05em;
}
.archive-sort-select {
  padding: 8px 16px;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: #fff;
  color: var(--txt);
  cursor: pointer;
  outline: none;
}

/* Grid */
.archive-grid {
  max-width: 1440px;
  margin: 0 auto 100px;
  padding: 0 48px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 36px 28px;
}
@media (max-width: 1200px) {
  .archive-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 860px) {
  .archive-grid { grid-template-columns: repeat(2, 1fr); padding: 0 24px; }
  .gazu-header { padding: 18px 24px; }
  .archive-hero { padding: 40px 24px 20px; }
  .archive-title { font-size: 28px; }
}
@media (max-width: 540px) {
  .archive-grid { grid-template-columns: 1fr; }
}

/* Card */
.p-card {
  background: #fff;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(0, 0, 0, 0.05);
  border-radius: 8px;
  overflow: hidden;
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.25s ease;
}
.p-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 36px rgba(0,0,0,0.08);
  border-color: rgba(0,0,0,0.12);
}
.p-card-media-wrap {
  position: relative;
  background: #fafafa;
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  overflow: hidden;
}
.p-card-cat-badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 3px 8px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #444;
  z-index: 2;
}
.p-card-img {
  max-width: 90%;
  max-height: 90%;
  object-fit: contain;
  filter: drop-shadow(0 12px 18px rgba(0,0,0,0.12));
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}
.p-card:hover .p-card-img {
  transform: scale(1.06) rotate(-2deg);
}
.p-card-overlay-actions {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}
.p-card:hover .p-card-overlay-actions {
  opacity: 1;
  pointer-events: auto;
}
.p-card-quickview-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #fff;
  color: #111;
  border: none;
  border-radius: 999px;
  padding: 10px 20px;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(0,0,0,0.2);
  transform: translateY(6px);
  transition: all 0.2s ease;
}
.p-card:hover .p-card-quickview-btn {
  transform: translateY(0);
}
.p-card-quickview-btn:hover {
  background: #111;
  color: #fff;
}

.p-card-content {
  padding: 20px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.p-card-title {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--txt);
  margin-bottom: 6px;
  line-height: 1.4;
}
.p-card-price {
  font-size: 15px;
  font-weight: 700;
  color: var(--txt);
  margin-bottom: 16px;
}
.p-card-currency {
  font-size: 11px;
  font-weight: 500;
  color: #888;
}

/* Sizes Pills */
.p-card-sizes {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}
.p-card-size-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: #999;
  margin-right: 4px;
}
.p-size-pill {
  background: #f4f4f4;
  border: 1px solid transparent;
  border-radius: 4px;
  min-width: 28px;
  height: 24px;
  padding: 0 6px;
  font-family: var(--font-body);
  font-size: 10px;
  font-weight: 600;
  color: #444;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s;
}
.p-size-pill:hover {
  border-color: #111;
  color: #111;
}
.p-size-pill.is-active {
  background: #111;
  color: #fff;
  border-color: #111;
}

.p-card-actions {
  margin-top: auto;
}
.p-card-add-btn {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: #111;
  color: #fff;
  border: 1px solid #111;
  border-radius: 6px;
  padding: 11px 16px;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s;
}
.p-card-add-btn:hover {
  background: #2a2a2a;
  border-color: #2a2a2a;
}

/* Status Notification */
.bag-status-toast {
  position: fixed;
  bottom: 28px;
  right: 28px;
  background: #111;
  color: #fff;
  padding: 14px 24px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.05em;
  box-shadow: 0 10px 30px rgba(0,0,0,0.25);
  opacity: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 1000;
}
.bag-status-toast.is-on {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

/* Quick View Dialog */
dialog {
  border: none;
  border-radius: 12px;
  padding: 0;
  box-shadow: 0 25px 60px rgba(0,0,0,0.3);
  max-width: 820px;
  width: 90vw;
  margin: auto;
}
dialog::backdrop {
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
}
.qv-modal-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  position: relative;
}
@media (max-width: 700px) {
  .qv-modal-body { grid-template-columns: 1fr; }
}
.qv-media {
  background: #f7f7f7;
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.qv-media img {
  max-width: 100%;
  max-height: 360px;
  object-fit: contain;
  filter: drop-shadow(0 14px 24px rgba(0,0,0,0.15));
}
.qv-info {
  padding: 40px;
  display: flex;
  flex-direction: column;
}
.qv-close-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 8px;
  border-radius: 50%;
  color: #666;
}
.qv-close-btn:hover { color: #000; background: #eee; }
.qv-cat {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #888;
  margin-bottom: 8px;
}
.qv-title {
  font-family: var(--font-head);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.qv-price {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
}
.qv-desc {
  font-size: 13px;
  color: #555;
  line-height: 1.6;
  margin-bottom: 20px;
}
.qv-details-list {
  list-style: none;
  margin-bottom: 24px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.qv-details-list li {
  font-size: 12px;
  color: #666;
  display: flex;
  align-items: center;
  gap: 8px;
}
.qv-details-list li::before {
  content: "•";
  color: #111;
  font-weight: bold;
}
.qv-sizes-wrap {
  margin-bottom: 24px;
}
.qv-sizes-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #444;
  margin-bottom: 8px;
}
.qv-sizes {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.qv-add-btn {
  width: 100%;
  background: #111;
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 14px;
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  cursor: pointer;
  margin-top: auto;
}
.qv-add-btn:hover { background: #2a2a2a; }

/* Bag Dialog */
.bag-dialog {
  border: none;
  border-radius: 12px;
  max-width: 500px;
  width: 90vw;
  margin: auto;
  padding: 30px;
}
.bag-dialog-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 20px;
}
.bag-dialog-title {
  font-family: var(--font-head);
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}
.bag-dialog-close {
  background: none;
  border: none;
  font-size: 20px;
  cursor: pointer;
  color: #888;
}
.bag-items-list {
  max-height: 380px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}
.bag-item-row {
  display: flex;
  align-items: center;
  gap: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}
.bag-item-img {
  width: 60px;
  height: 60px;
  object-fit: contain;
  background: #f7f7f7;
  border-radius: 6px;
  padding: 6px;
}
.bag-item-meta {
  flex-grow: 1;
}
.bag-item-title {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.3;
  margin-bottom: 4px;
}
.bag-item-price {
  font-size: 12px;
  font-weight: 700;
  color: #666;
}
.bag-item-del {
  background: none;
  border: none;
  color: #999;
  cursor: pointer;
  padding: 4px;
}
.bag-item-del:hover { color: #e53935; }
.bag-total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 14px;
  border-top: 1px solid var(--border);
  margin-bottom: 20px;
  font-size: 16px;
  font-weight: 700;
}
.bag-checkout-btn {
  width: 100%;
  background: #111;
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 14px;
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  cursor: pointer;
}
.bag-checkout-btn:hover { background: #2a2a2a; }

/* Footer */
.archive-footer {
  border-top: 1px solid var(--border);
  padding: 40px 48px;
  text-align: center;
  font-size: 12px;
  color: #888;
  letter-spacing: 0.1em;
}

scripts.inline:
const STORAGE_KEY = 'runway-styling-bag-v3';

// Size Pill Click Handlers in Card
document.addEventListener('click', e => {
  const sizePill = e.target.closest('.p-card .p-size-pill');
  if (sizePill) {
    const container = sizePill.closest('.p-card-sizes');
    container.querySelectorAll('.p-size-pill').forEach(p => p.classList.remove('is-active'));
    sizePill.classList.add('is-active');
    container.setAttribute('data-selected-size', sizePill.getAttribute('data-size'));
  }
  const qvSizePill = e.target.closest('.qv-sizes .p-size-pill');
  if (qvSizePill) {
    const container = qvSizePill.closest('.qv-sizes');
    container.querySelectorAll('.p-size-pill').forEach(p => p.classList.remove('is-active'));
    qvSizePill.classList.add('is-active');
  }
});

// Add to Bag Handlers
function showToast(msg) {
  const toast = document.getElementById('bag-toast');
  toast.textContent = msg;
  toast.classList.add('is-on');
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => toast.classList.remove('is-on'), 3000);
}

function getBag() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
  } catch (_) { return []; }
}

function saveBag(bag) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(bag));
  updateBagCount();
}

function updateBagCount() {
  const bag = getBag();
  const count = bag.reduce((sum, item) => sum + (item.quantity || 1), 0);
  document.querySelectorAll('#header-bag-count').forEach(el => el.textContent = count);
}

function addToBag(item) {
  const bag = getBag();
  const existing = bag.find(i => i.id === item.id && i.size === item.size);
  if (existing) {
    existing.quantity = (existing.quantity || 1) + 1;
  } else {
    bag.push({
      id: item.id,
      variantId: item.variantId,
      title: item.title,
      price: item.price,
      img: item.img,
      size: item.size,
      quantity: 1
    });
  }
  saveBag(bag);
  showToast(`${item.title} (Size ${item.size}) saved to styling bag`);
}

document.addEventListener('click', e => {
  const addBtn = e.target.closest('[data-action="add-to-bag"]');
  if (addBtn) {
    const card = addBtn.closest('.p-card');
    const sizeContainer = card.querySelector('.p-card-sizes');
    const size = sizeContainer ? sizeContainer.getAttribute('data-selected-size') || '42' : '42';
    addToBag({
      id: addBtn.getAttribute('data-id'),
      variantId: addBtn.getAttribute('data-variant'),
      title: addBtn.getAttribute('data-title'),
      price: parseFloat(addBtn.getAttribute('data-price-num')),
      img: addBtn.getAttribute('data-img'),
      size: size
    });
  }
});

// Quick View Modal
const qvDialog = document.getElementById('quickview-dialog');
let currentQvItem = null;

document.addEventListener('click', e => {
  const qvBtn = e.target.closest('[data-action="quickview"]');
  if (qvBtn) {
    const details = JSON.parse(qvBtn.getAttribute('data-details') || '[]');
    currentQvItem = {
      id: qvBtn.getAttribute('data-id'),
      variantId: qvBtn.getAttribute('data-variant'),
      title: qvBtn.getAttribute('data-title'),
      price: qvBtn.getAttribute('data-price'),
      priceNum: parseFloat(qvBtn.getAttribute('data-price-num')),
      category: qvBtn.getAttribute('data-category'),
      img: qvBtn.getAttribute('data-img'),
      desc: qvBtn.getAttribute('data-desc')
    };

    document.getElementById('qv-img').src = currentQvItem.img;
    document.getElementById('qv-cat').textContent = currentQvItem.category;
    document.getElementById('qv-title').textContent = currentQvItem.title;
    document.getElementById('qv-price').textContent = currentQvItem.price + ' USD';
    document.getElementById('qv-desc').textContent = currentQvItem.desc;

    const detailsList = document.getElementById('qv-details');
    detailsList.innerHTML = details.map(d => `<li>${d}</li>`).join('');

    qvDialog.showModal();
  }
});

document.getElementById('qv-close-btn').addEventListener('click', () => qvDialog.close());
qvDialog.addEventListener('click', e => {
  if (e.target === qvDialog) qvDialog.close();
});

document.getElementById('qv-add-btn').addEventListener('click', () => {
  if (!currentQvItem) return;
  const activeSize = document.querySelector('#qv-sizes .p-size-pill.is-active')?.getAttribute('data-size') || '42';
  addToBag({
    id: currentQvItem.id,
    variantId: currentQvItem.variantId,
    title: currentQvItem.title,
    price: currentQvItem.priceNum,
    img: currentQvItem.img,
    size: activeSize
  });
  qvDialog.close();
});

// Bag Dialog Render
const bagDialog = document.getElementById('bag-dialog');
document.getElementById('open-bag-btn').addEventListener('click', () => {
  renderBagModal();
  bagDialog.showModal();
});
document.getElementById('bag-dialog-close').addEventListener('click', () => bagDialog.close());
bagDialog.addEventListener('click', e => {
  if (e.target === bagDialog) bagDialog.close();
});

function renderBagModal() {
  const bag = getBag();
  const list = document.getElementById('bag-items-list');
  if (!bag.length) {
    list.innerHTML = '<p style="text-align:center; color:#888; padding:30px;">Your styling bag is empty.</p>';
    document.getElementById('bag-subtotal').textContent = '$0.00 USD';
    return;
  }
  let total = 0;
  list.innerHTML = bag.map((it, idx) => {
    const p = it.price || 149;
    const q = it.quantity || 1;
    total += p * q;
    return `
      <div class="bag-item-row">
        <img src="${it.img}" alt="" class="bag-item-img">
        <div class="bag-item-meta">
          <div class="bag-item-title">${it.title}</div>
          <div class="bag-item-price">$${p.toFixed(2)} &times; ${q} ${it.size ? `(Size ${it.size})` : ''}</div>
        </div>
        <button type="button" class="bag-item-del" onclick="removeBagItem(${idx})" aria-label="Remove">&times;</button>
      </div>
    `;
  }).join('');
  document.getElementById('bag-subtotal').textContent = `$${total.toFixed(2)} USD`;
}

window.removeBagItem = function(index) {
  const bag = getBag();
  bag.splice(index, 1);
  saveBag(bag);
  renderBagModal();
};

// Filter and Sort Handlers
const filterBtns = document.querySelectorAll('.archive-filter-btn');
const sortSelect = document.getElementById('sort-select');
const cards = Array.from(document.querySelectorAll('.p-card'));
const grid = document.getElementById('products-grid');
const resultsCount = document.getElementById('results-count');

function updateGrid() {
  const activeFilter = document.querySelector('.archive-filter-btn.is-active').getAttribute('data-filter');
  const sortVal = sortSelect.value;

  let visible = cards.filter(card => {
    if (activeFilter === 'all') return true;
    return card.getAttribute('data-category') === activeFilter;
  });

  visible.sort((a, b) => {
    const priceA = parseFloat(a.getAttribute('data-price'));
    const priceB = parseFloat(b.getAttribute('data-price'));
    const titleA = a.querySelector('.p-card-title').textContent.trim();
    const titleB = b.querySelector('.p-card-title').textContent.trim();

    if (sortVal === 'price-asc') return priceA - priceB;
    if (sortVal === 'price-desc') return priceB - priceA;
    if (sortVal === 'title-asc') return titleA.localeCompare(titleB);
    return 0; // featured default
  });

  cards.forEach(c => c.style.display = 'none');
  visible.forEach(c => {
    c.style.display = 'flex';
    grid.appendChild(c);
  });

  resultsCount.textContent = `Showing ${visible.length} silhouettes`;
}

filterBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    filterBtns.forEach(b => b.classList.remove('is-active'));
    btn.classList.add('is-active');
    updateGrid();
  });
});

sortSelect.addEventListener('change', updateGrid);

// Initial Bag Count
updateBagCount();

